  "Kvöld-/morgunálag": { is: "Kvöld-/morgunálag", en: "Evening/morning premium", vi: "Phụ cấp tối/sáng", pl: "Dodatek wieczorny/poranny" },
  "Helgarálag": { is: "Helgarálag", en: "Weekend premium", vi: "Phụ cấp cuối tuần", pl: "Dodatek weekendowy" },
  "Stórhátíðarálag": { is: "Stórhátíðarálag", en: "Public holiday premium", vi: "Phụ cấp ngày lễ lớn", pl: "Dodatek świąteczny" },
  "Álag / yfirvinna (%)": { is: "Álag / yfirvinna (%)", en: "Premium / Overtime (%)", vi: "Phụ cấp / tăng ca (%)", pl: "Dodatek / nadgodziny (%)" },
  "Ég staðfesti að þetta stemmir við kjarasamninginn": { is: "Ég staðfesti að þetta samræmist viðkomandi kjarasamningi", en: "I confirm this complies with the active union agreement", vi: "Tôi xác nhận nội dung này phù hợp với thỏa ước lao động hiện hành", pl: "Potwierdzam, że jest to zgodne z odpowiednim układem zbiorowym" },
  "Berðu saman við réttan samning (Efling/VR/SGS) áður en þú staðfestir.": { is: "Berið saman við viðeigandi kjarasamning (Efling / VR / SGS) áður en gengið er frá staðfestingu.", en: "Verify accuracy against the official agreement template (Efling/VR/SGS) before confirmation.", vi: "Hãy đối chiếu với thỏa ước lao động chính thức (Efling/VR/SGS) trước khi xác nhận.", pl: "Porównaj z właściwym układem zbiorowym (Efling / VR / SGS) przed potwierdzeniem." },
  "⚠️ Prósenturnar eru staðlað sniðmát — staðfestu hverja gegn raunverulegum kjarasamningi (Efling/VR) áður en þær eru notaðar á laun.": { is: "⚠️ Prósenturnar eru staðlað viðmiðunarsniðmát — Samræmdu prósentur við gildandi kjarasamninga (Efling / VR) áður en laun eru keyrð.", en: "⚠️ Percentages are based on general templates — Ensure exact compliance with the actual union agreement (Efling/VR) prior to processing payroll.", vi: "⚠️ Các tỷ lệ phần trăm chỉ là mẫu chuẩn — hãy đối chiếu từng mục với thỏa ước lao động thực tế (Efling/VR) trước khi áp dụng vào lương.", pl: "⚠️ Procenty to standardowy szablon referencyjny — dopasuj je do obowiązujących układów zbiorowych (Efling / VR) przed naliczeniem wynagrodzeń." },
  "af 4 skrefum kláruð — settu kerfið upp á nokkrum mínútum.": { is: "af 4 skrefum lokið — Uppsetning klárast á nokkrum mínútum.", en: "of 4 configuration steps completed — Set up the platform in minutes.", vi: "trên 4 bước đã hoàn thành — Thiết lập hệ thống chỉ trong vài phút.", pl: "z 4 kroków ukończono — konfiguracja zajmie kilka minut." },
  "Skrá veltu / tengja Inventra": { is: "Skrá veltu / tengja sölukerfi", en: "Log revenue / connect your POS", vi: "Ghi doanh thu / kết nối POS", pl: "Wpisz obrót / połącz system sprzedaży" },
  "Þegar þú hefur bætt við starfsfólki og birt vaktaplan birtast hér lifandi tölur — laun af tekjum, launakostnaður, frávik og yfirvinna.": { is: "Þegar starfsfólki hefur verið bætt við og vaktaplan gefið út uppfærast rauntölur hér: Launahlutfall, raunkostnaður, frávik og yfirvinnustundir.", en: "Once personnel are added and a schedule is published, live metrics like labor% of revenue, labor burden, variances, and overtime tracking will appear here.", vi: "Khi đã thêm nhân viên và đăng lịch làm việc, các số liệu trực tiếp sẽ hiện ở đây — lương trên doanh thu, chi phí lương, chênh lệch và tăng ca.", pl: "Po dodaniu pracowników i opublikowaniu grafiku pojawią się tu dane na żywo: udział wynagrodzeń, rzeczywisty koszt, odchylenia i nadgodziny." },
