  "role:manager": { is: "Rekstrarstjóri", en: "Manager", vi: "Quản lý", pl: "Kierownik operacyjny" },
  "role:employee": { is: "Starfsmaður", en: "Employee", vi: "Nhân viên", pl: "Pracownik" },
