  "Virkir síðustu 30 daga": { is: "Virkir síðustu 30 daga", en: "Active last 30 days", vi: "Hoạt động 30 ngày qua", pl: "Aktywni w ostatnich 30 dniach" },
  "Áætlað á mánuði": { is: "Áætlað á mánuði", en: "Estimated per month", vi: "Ước tính mỗi tháng", pl: "Szacunkowo miesięcznie" },
  "m. VSK": { is: "m. VSK", en: "incl. VAT", vi: "gồm VAT", pl: "z VAT" },
  "Rafræn skilríki (valkvætt)": { is: "Rafræn skilríki (valkvætt)", en: "Electronic ID (optional)", vi: "ID điện tử (tùy chọn)", pl: "Podpis elektroniczny (opcjonalnie)" },
  "á undirskrift (án VSK)": { is: "á undirskrift (án VSK)", en: "per signature (excl. VAT)", vi: "mỗi chữ ký (chưa VAT)", pl: "za podpis (bez VAT)" },
  "Virkur starfsmaður = átti vakt eða stimplaði sig á tímabilinu. Grunngjaldið er greitt fyrirfram; virkir umfram 5 og undirskriftir eru gerð upp eftir á fyrir mánuðinn sem lauk.": { is: "Virkur starfsmaður = átti vakt eða stimplaði sig á tímabilinu. Grunngjaldið er greitt fyrirfram; virkir umfram 5 og undirskriftir eru gerð upp eftir á fyrir mánuðinn sem lauk.", en: "An active employee had a shift or clocked in during the period. The base fee is paid in advance; active employees beyond 5 and signatures are settled afterwards for the month that ended.", vi: "Nhân viên hoạt động = có ca hoặc chấm công trong kỳ. Phí cơ bản trả trước; nhân viên vượt 5 và chữ ký được thanh toán sau cho tháng đã qua.", pl: "Aktywny pracownik = miał zmianę lub odbił czas pracy w okresie. Opłata podstawowa jest płatna z góry; aktywni ponad 5 oraz podpisy są rozliczane z dołu za miniony miesiąc." },
  "Virkir / notendur": { is: "Virkir / notendur", en: "Active / users", vi: "Hoạt động / người dùng", pl: "Aktywni / użytkownicy" },
  "undirskr.": { is: "undirskr.", en: "signatures", vi: "chữ ký", pl: "podpisy" },
  "Greiðsla": { is: "Greiðsla", en: "Billing", vi: "Thanh toán", pl: "Płatność" },
  "Mánaðarlega": { is: "Mánaðarlega", en: "Monthly", vi: "Hàng tháng", pl: "Miesięcznie" },
  "Árlega · 15% afsláttur": { is: "Árlega · 15% afsláttur", en: "Yearly · 15% off", vi: "Hàng năm · giảm 15%", pl: "Rocznie · 15% zniżki" },
  "Árleg greiðsla tekur gildi á næsta gjalddaga": { is: "Árleg greiðsla tekur gildi á næsta gjalddaga", en: "Yearly billing starts on the next due date", vi: "Thanh toán hàng năm bắt đầu vào kỳ tới", pl: "Płatność roczna zacznie obowiązywać od następnego terminu płatności" },
