  "Árið er greitt til": { is: "Árið er greitt til", en: "The year is paid until", vi: "Năm đã được thanh toán đến", pl: "Rok jest opłacony do" },
  "Greitt ár gildir til": { is: "Greitt ár gildir til", en: "The paid year runs until", vi: "Năm đã trả có hiệu lực đến", pl: "Opłacony rok obowiązuje do" },
  "; mánaðarleg greiðsla tekur við eftir það.": { is: "; mánaðarleg greiðsla tekur við eftir það.", en: "; monthly billing takes over after that.", vi: "; sau đó chuyển sang thanh toán hàng tháng.", pl: "; potem obowiązuje płatność miesięczna." },
  "Árgjaldið": { is: "Árgjaldið", en: "The annual fee", vi: "Phí hàng năm", pl: "Opłata roczna" },
  "verður tekið á næsta gjalddaga": { is: "verður tekið á næsta gjalddaga", en: "will be charged on the next due date", vi: "sẽ được thu vào kỳ tới", pl: "zostanie pobrana w następnym terminie płatności" },
  "Virkir umfram 5 eru gerðir upp mánaðarlega á árlegum kjörum.": { is: "Virkir umfram 5 eru gerðir upp mánaðarlega á árlegum kjörum.", en: "Active employees beyond 5 are settled monthly at the yearly rate.", vi: "Nhân viên vượt 5 được thanh toán hàng tháng theo giá năm.", pl: "Aktywni ponad 5 są rozliczani miesięcznie według warunków rocznych." },
  "Engar vinnustundir eru skráðar á tímabilinu og engin laun voru greidd.": { is: "Engar vinnustundir eru skráðar á tímabilinu og engin laun voru greidd.", en: "No working hours were recorded in the period and no pay was issued.", vi: "Không có giờ làm trong kỳ và không có lương được trả.", pl: "W tym okresie nie zarejestrowano godzin pracy i nie wypłacono wynagrodzenia." },
